package com.afaq.iman;import android.appwidget.AppWidgetManager;import android.content.ComponentName;import android.content.Context;import android.content.SharedPreferences;import com.getcapacitor.JSObject;import com.getcapacitor.Plugin;import com.getcapacitor.PluginCall;import com.getcapacitor.annotation.CapacitorPlugin;import com.getcapacitor.PluginMethod;
@CapacitorPlugin(name="PrayerWidget") public class PrayerWidgetPlugin extends Plugin{@PluginMethod public void update(PluginCall call){Context c=getContext();SharedPreferences p=c.getSharedPreferences("afaq_widget",Context.MODE_PRIVATE);p.edit().putString("prayer",call.getString("prayer","الصلاة القادمة")).putString("city",call.getString("city","")).putLong("target",call.getLong("target",System.currentTimeMillis())).apply();int[] ids=AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,PrayerWidgetProvider.class));PrayerWidgetProvider.updateAll(c,ids);call.resolve(new JSObject());}}
